import json
from sympy import symbols
from sympy.logic.boolalg import SOPform, And, Or, Not, BooleanTrue, BooleanFalse

spec = TASK["public"]["specification"]
xs = symbols("x0:10")
mins = [tuple(row) for row, y in zip(spec["inputs"], spec["outputs"]) if y]
expr = SOPform(xs, mins)

gates = []
def compile_expr(e, neg=False):
    if e == BooleanTrue:
        return ("const", 1 ^ int(neg))
    if e == BooleanFalse:
        return ("const", int(neg))
    if e.func == Not:
        return compile_expr(e.args[0], not neg)
    if e in xs:
        return ("lit", ("x", xs.index(e)), neg)
    if e.func in (And, Or):
        is_and = (e.func == And) != neg
        args = [compile_expr(a, neg) for a in e.args]
        gates.append(("and" if is_and else "or", args))
        return ("gate", len(gates) - 1, False)
    raise ValueError(f"Unsupported expression node: {e}")

root = compile_expr(expr)

depth = {}
def gate_depth(i):
    if i not in depth:
        depth[i] = 1 + max(
            (gate_depth(a[1]) for a in gates[i][1] if a[0] == "gate"),
            default=0
        )
    return depth[i]

for i in range(len(gates)):
    gate_depth(i)

stages = [[] for _ in range(4)]
for i in range(len(gates)):
    d = depth[i] - 1
    if d >= 4:
        raise ValueError("Boolean circuit needs more than four stages")
    stages[d].append(i)

# A gate's register remains live through its final consumer, or through
# stage 4 if it is the root used by the output head.
last = {i: depth[i] for i in range(len(gates))}
for consumer, (_, args) in enumerate(gates):
    for a in args:
        if a[0] == "gate":
            parent = a[1]
            last[parent] = max(last[parent], depth[consumer] - 1)
if root[0] == "gate":
    last[root[1]] = 4

# Interval-color the eight available Boolean-signal registers.
slots = {}
for i in sorted(range(len(gates)), key=lambda g: (depth[g], g)):
    start, end = depth[i], last[i]
    used = {
        slots[j] for j in slots
        if depth[j] <= end and last[j] >= start
    }
    free = [s for s in range(8) if s not in used]
    if not free:
        raise ValueError("Circuit needs more than eight live signal registers")
    slots[i] = free[0]

patch = []
def setv(tensor, index, value):
    if value:
        patch.append({"op": "set", "tensor": tensor, "index": index, "value": float(value)})

# Each signal is represented by h[j] - h[j+2]. For both AND and OR,
# ReLU(s + b) - ReLU(s + b - 1) produces an exact Boolean indicator.
for layer, wname in enumerate(("w0", "w1", "w2", "w3"), start=1):
    bname = f"b{layer-1}"

    for j in range(10):
        setv(wname, [j, j], 1)

    # Carry signals whose registers remain live from the previous layer.
    for i in range(len(gates)):
        if depth[i] < layer and last[i] >= layer:
            base = 10 + 3 * slots[i]
            for off in range(3):
                setv(wname, [base + off, base + off], 1)

    for gi in stages[layer - 1]:
        kind, args = gates[gi]
        base = 10 + 3 * slots[gi]
        coeffs, bias = {}, 0

        for a in args:
            if a[0] == "lit":
                ref, neg = a[1], a[2]
                if ref[0] == "x":
                    components = [(ref[1], 1)]
                else:
                    p = 10 + 3 * slots[ref[1]]
                    components = [(p, 1), (p + 2, -1)]
            else:
                neg = a[2]
                p = 10 + 3 * slots[a[1]]
                components = [(p, 1), (p + 2, -1)]

            sign = -1 if neg else 1
            for channel, weight in components:
                coeffs[channel] = coeffs.get(channel, 0) + sign * weight
            if neg:
                bias += 1

        n = len(args)
        offset = (1 - n) if kind == "and" else 0
        for channel, value in coeffs.items():
            setv(wname, [base, channel], value)
            setv(wname, [base + 2, channel], value)
        setv(bname, [base], bias + offset)
        setv(bname, [base + 2], bias + offset - 1)

# Read the final root signal from its carried register.
if root[0] == "const":
    setv("bias", [1], root[1])
else:
    if root[0] == "lit":
        ref, root_neg = root[1], root[2]
        if ref[0] == "x":
            components = [(ref[1], 1)]
        else:
            p = 10 + 3 * slots[ref[1]]
            components = [(p, 1), (p + 2, -1)]
    else:
        root_neg = root[2]
        p = 10 + 3 * slots[root[1]]
        components = [(p, 1), (p + 2, -1)]

    sign = -1 if root_neg else 1
    for channel, weight in components:
        setv("out", [1, channel], sign * weight)
    setv("bias", [1], 1 if root_neg else 0)

sub = {"patch": patch}
check_submission(sub)
with open("/work/submission.json", "w") as f:
    json.dump(sub, f)
